"""Accounts of harvests. Rate lookups are billed, so each account remembers its charge."""
import rates


class HarvestAccount:
    entries = []

    def __init__(self, name):
        self.name = name
        self._charge = None

    def add(self, harvest):
        """Add one harvest to this account."""
        self.entries.append(harvest)
        self._charge = None

    def charge(self):
        """Return this account's charge: kilos times the rate for each harvest's field.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.kilos * rates.rate_for(x.field) for x in self.entries)
        return self._charge


def describe_harvest(harvest):
    """Return a one-line description of a harvest."""
    return "%s: %s" % (harvest.field, harvest.kilos)
